#!/bin/bash
# FILENAME: 2_decon_DAPI.sh
# DESCRIPTION: Deconwolf deconvolution of the DAPI channel into decon-images/.
# Generated by slurm_scripts/script.py (Anvil). Step bodies follow aws_templates/aws_s3_template/.

#SBATCH -A mcb130189-gpu
#SBATCH -p gpu
#SBATCH -t {T_DECON}
#SBATCH --nodes=1
#SBATCH --gpus-per-node=1
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=64
#SBATCH --mem=256gb
#SBATCH -J decon_DAPI_{EXP_N}_{REG_N}
#SBATCH -o {LOG_DIR}/2_decon_DAPI_{EXP_N}_{REG_N}.out
#SBATCH -e {LOG_DIR}/2_decon_DAPI_{EXP_N}_{REG_N}.out

module purge
module load modtree/gpu
module load gsl
module load libtiff
module load libpng
module load fftw
LD_LIBRARY_PATH=${{LD_LIBRARY_PATH:-}}:/anvil/projects/x-mcb130189/aklein/programs/gsl/lib
module list

# Fail fast from here on: any non-zero exit aborts the job, so --dependency=afterok in chain.sh stops
# downstream steps. Module loads above stay non-fatal (not every module exists on every node type).
set -eo pipefail  # no -u: Lmod module functions read unset variables

export PATH="/home/x-aklein2/.pixi/bin:$PATH"
export SLURM_TMPDIR="${{SLURM_TMPDIR:-${{TMPDIR:-/tmp}}}}"
export PIXI_HOME="${{SLURM_TMPDIR}}/pixi_home_${{SLURM_JOB_ID:-$$}}"
export PIXI_CACHE_DIR="/anvil/projects/x-mcb130189/aklein/.cache/rattler/cache"
export RATTLER_CACHE_DIR="/anvil/projects/x-mcb130189/aklein/.cache/rattler/cache"
mkdir -p "$PIXI_HOME" "$PIXI_CACHE_DIR" "$RATTLER_CACHE_DIR"

# Run from a copy of SPIDA: edits to the source tree cannot reach a running job.
WORKDIR="${{SLURM_TMPDIR}}/spida_${{SLURM_JOB_ID:-$$}}"
rsync -a --delete --exclude '.pixi/envs' "{SPIDA_ROOT}/" "$WORKDIR/"
cd "$WORKDIR"
pixi install --frozen -e preprocessing-gpu

# --- Compute ---
# Deconvolved planes go to {DECON_DIR} (next to the raw images/, which stay untouched).
echo -e "\nRunning whole image deconvolution - DAPI - {REG_N} - {EXP_N}\n"
mkdir -p {DECON_DIR}
pixi run --frozen -e preprocessing-gpu \
    python -m spida.S.cli --config {CONFIG_PATH} \
    transform-image \
    -i {ROOT_DIR}/{EXPERIMENT}/out/{REGION}/images \
    --data_org_path {DATA_ORG_PATH} \
    --tile_dir {ROOT_DIR}/{EXPERIMENT}/{REGION}/tile_images_DAPI \
    --stitched_dir {DECON_DIR} \
    --channels DAPI \
    --tile_size 2960 \
    --overlap 400 \
    --z_step 1.5 \
    --transform deconwolf \
    {DECON_FILTER_ARGS}\
    --gpu \
    --plot_thr
